/* Executable teaching examples. All shapes include batch; examples use B=1. */
const computationState={timer:null,selection:0,head:0,key:''};
const calcSum=a=>a.reduce((s,x)=>s+x,0);
const calcDot=(a,b)=>calcSum(a.map((x,i)=>x*b[i]));
const calcTranspose=a=>a[0].map((_,c)=>a.map(row=>row[c]));
const calcMM=(a,b)=>a.map(row=>calcTranspose(b).map(col=>calcDot(row,col)));
const calcSoftmax=a=>{const e=a.map(x=>Math.exp(x-Math.max(...a))),s=calcSum(e);return e.map(x=>x/s);};
function dotWitness(label,a,b,refs=[]){return{label,terms:a.map((x,i)=>({expression:modelNum(x)+' × '+modelNum(b[i]),value:x*b[i],refs:refs[i]||[]})),result:calcDot(a,b),sum:true};}
function stepsWitness(label,steps){return {label,terms:steps.map(([expression,value])=>({expression,value})),result:steps.at(-1)[1],sum:false};}
function mlaExample(){
 const X=[[1,2,0,1],[0,1,2,1],[2,0,1,1]],WDKV=[[1,0],[0,1],[1,0],[0,1]],WKR=[[1,0],[0,0],[0,0],[0,1]],WDQ=[[1,0],[0,1],[0,1],[1,0]],WUQ=[[1,0,0,1],[0,1,1,0]],WUK=[[1,0,1,1],[0,1,1,-1]],WUV=[[1,0,2,0],[0,1,0,1]],C=calcMM(X,WDKV),rawKR=calcMM(X,WKR),KR=rawKR.map(([a,b],i)=>i===0?[a,b]:i===1?[-b,a]:[-a,-b]),cQ=calcMM([X[2]],WDQ)[0],expandedQ=calcMM([cQ],WUQ)[0];
 const heads=[0,1].map(h=>{const UK=WUK.map(r=>r.slice(h*2,h*2+2)),UV=WUV.map(r=>r.slice(h*2,h*2+2)),qC=expandedQ.slice(h*2,h*2+2),qR=qC.map(x=>-x),K=calcMM(C,UK),V=calcMM(C,UV),content=K.map(k=>calcDot(qC,k)),rotary=KR.map(k=>calcDot(qR,k)),scores=content.map((v,i)=>(v+rotary[i])/2),weights=calcSoftmax(scores),qLatent=calcMM([qC],calcTranspose(UK))[0],absorbed=C.map((c,i)=>(calcDot(qLatent,c)+calcDot(qR,KR[i]))/2),z=calcMM([weights],C)[0],o=calcMM([weights],V)[0],absorbedO=calcMM([z],UV)[0];return{UK,UV,qC,qR,K,V,content,rotary,scores,weights,qLatent,absorbed,z,o,absorbedO};});
 return{X,WDKV,WKR,WDQ,WUQ,WUK,WUV,C,rawKR,KR,cQ,heads,output:heads.flatMap(h=>h.o),compactPerToken:4,expandedPerToken:12};
}
setModelFrames('mla',[
 ['Compress the KV content path','压缩 KV 内容路径','Multiply each 4-feature history row by the learned 4×2 down-projection. Token 0 gives [1+0, 2+1]=[1,3]. This shared 2-feature latent will supply both content keys and values.','每个四维历史行乘学习到的 4×2 下投影。token 0 得到 [1+0,2+1]=[1,3]；此共享二维潜变量将提供内容键和值。'],
 ['Make current-token query branches','生成当前 token 的查询分支','Current x=[2,0,1,1] compresses to cQ=[3,1], then expands into two heads. Each head has separate content and rotary query features. Query compression is temporary; it is not a history cache.','当前 x=[2,0,1,1] 压缩为 cQ=[3,1]，再展开成两个头；每头分为内容查询与旋转查询。查询压缩是临时计算，不是历史缓存。'],
 ['Keep position separate from content','把位置与内容分开','A separate 4×2 projection produces rotary keys. Rotate the three positions by 0°, 90°, 180°. Only this rotary slice receives RoPE; the shared content latent is left unrotated.','独立 4×2 投影生成旋转键，三个位置分别旋转 0°、90°、180°。只有旋转切片使用 RoPE，共享内容潜变量不旋转。'],
 ['Cache exactly two tensors','仅缓存两个张量','Retain C_KV[1,3,2] and K_R[1,3,2]. Each new token appends one row to each. Do not retain current-token queries, or materialize per-head K_C and V in this compact-cache decode path.','保留 C_KV[1,3,2] 与 K_R[1,3,2]，每个新 token 各追加一行。此紧凑缓存解码路径不保留当前查询，也不物化逐头 K_C、V。'],
 ['Expand conceptually to see the keys and values','概念展开以理解键和值','For the selected head, K_C=C_KV·W_UK and V=C_KV·W_UV. Both come from the same latent, but different learned projections. These explicit matrices explain the algebra; optimized decode can avoid storing them.','对所选头，K_C=C_KV·W_UK，V=C_KV·W_UV。二者来自同一潜变量，但使用不同学习投影。显式矩阵用于解释代数，优化解码可避免存储它们。'],
 ['Calculate content plus position scores','计算内容与位置评分','For every visible token, add q_C·k_C to q_R·k_R, then divide by √(dN+dR)=2. Both branches contribute to one score before the single softmax.','对每个可见 token，将 q_C·k_C 与 q_R·k_R 相加，再除以 √(dN+dR)=2。两分支共同形成一个评分，再做一次 softmax。'],
 ['Absorb the key up-projection','吸收键上投影','Reassociate q_C(C_KV W_UK)ᵀ as (q_C W_UKᵀ)C_KVᵀ. The transformed query scores cached latents directly; the rotary score is still added separately. This is exact algebra for the learned projections.','将 q_C(C_KV W_UK)ᵀ 结合为 (q_C W_UKᵀ)C_KVᵀ。变换查询直接对缓存潜变量评分，旋转评分仍单独相加。对这些学习投影而言，此变换是精确代数。'],
 ['Normalize, then read the latent cache','归一化后读取潜变量缓存','Softmax spans the three visible history rows. Form z=weights·C_KV, a 2-feature weighted latent. It carries the value information needed by this head.','softmax 覆盖三个可见历史行；形成 z=weights·C_KV，即二维加权潜变量，包含该头需要的值信息。'],
 ['Project values and merge head outputs','投影值并合并各头输出','Compute o_h=z_h W_UV,h. It equals weights·V_h. Concatenate two 2-feature head outputs and apply W_O; the miniature example uses W_O=I₄. The output shape is [1,1,4].','计算 o_h=z_h W_UV,h，与 weights·V_h 相同。拼接两个二维头输出后应用 W_O；小示例令 W_O=I₄。输出形状为 [1,1,4]。'],
 ['Account for what is stored','核算存储内容','The toy caches 2 latent + 2 rotary scalars per token. A naïve per-head expanded cache uses 2×(2+2+2)=12. V3’s published dimensions give 512+64=576; this is a separate checkpoint scale, not the toy latent size.','示例每 token 缓存 2 个潜变量 + 2 个旋转标量；朴素逐头展开缓存使用 2×(2+2+2)=12。V3 公开维度给出 512+64=576，这是独立检查点规模，并非示例潜变量大小。']
]);
function mlaContract(f){const d=mlaExample(),h=d.heads[computationState.head],st=Math.min(f.stage,9);let traces=[];
 if(st===0)for(let r=0;r<3;r++)for(let c=0;c<2;c++)traces.push(dotWitness('C_KV['+r+','+c+']',d.X[r],d.WDKV.map(row=>row[c]),d.X[r].map((_,i)=>[{matrix:'X · [3,4]',row:r,col:i},{matrix:'W_DKV · [4,2]',row:i,col:c}])));
 if(st===1)traces=[dotWitness('cQ[0]',d.X[2],d.WDQ.map(r=>r[0])),dotWitness('cQ[1]',d.X[2],d.WDQ.map(r=>r[1]))];
 if(st===2)traces=[stepsWitness(MT('Rotate position 1','旋转位置 1'),[['kR = [0,1]','[0,1]'],['θ = π/2; cos θ=0, sin θ=1','[0,1]'],['[a cosθ − b sinθ, a sinθ + b cosθ]','[−1,0]']])];
 if(st===3||st===9)traces=[stepsWitness(MT('Toy compact cache','示例紧凑缓存'),[['rKV',2],['dR',2],['rKV + dR = 2 + 2',4]]),stepsWitness(MT('Toy expanded cache','示例展开缓存'),[['H',2],['dN + dR + dV',6],['H(dN+dR+dV) = 2×6',12]]),stepsWitness(MT('V3 compact cache','V3 紧凑缓存'),[['rKV',512],['dR',64],['rKV + dR = 512 + 64',576]])];
 if(st===4)traces=[dotWitness('K_C[0,0]',d.C[0],h.UK.map(r=>r[0])),dotWitness('V[0,0]',d.C[0],h.UV.map(r=>r[0]))];
 if(st===5)traces=h.scores.map((v,i)=>stepsWitness('score['+i+']',[[h.qC.map((x,j)=>modelNum(x)+'×'+modelNum(h.K[i][j])).join(' + '),h.content[i]],[h.qR.map((x,j)=>modelNum(x)+'×'+modelNum(d.KR[i][j])).join(' + '),h.rotary[i]],['('+modelNum(h.content[i])+' + '+modelNum(h.rotary[i])+') / 2',v]]));
 if(st===6)traces=[0,1].map(c=>dotWitness('q_latent['+c+']',h.qC,h.UK[c]));
 if(st===7)traces=[0,1].map(c=>dotWitness('z['+c+']',h.weights,d.C.map(row=>row[c])));
 if(st===8)traces=[0,1].map(c=>dotWitness('o['+c+']',h.z,h.UV.map(row=>row[c])));
 return{input:'X [B,S,D]; x_query [B,T,D]',output:'Y [B,T,D]',state:'C_KV [B,S,rKV] + K_R [B,S,dR]; Q is temporary',axes:MT('B=batch; S=visible history; T=current query count; D=model width; H=heads; dN=content Q/K; dR=rotary Q/K; dV=value width; rKV,rQ=latent widths.','B=批次；S=可见历史；T=当前查询数；D=模型宽度；H=头数；dN=内容 Q/K；dR=旋转 Q/K；dV=值宽；rKV、rQ=潜变量宽度。'),equation:['C_KV = X W_DKV; [B,S,D] × [D,rKV] → [B,S,rKV]','cQ=x_query W_DQ; qC,qR=split(cQ W_UQ)','K_R=RoPE(X W_KR); qR=RoPE(qR); C_KV is not rotated','cache ← (C_KV, K_R); per token: rKV + dR','K_C,h=C_KV W_UK,h; V_h=C_KV W_UV,h','scores_h=(qC,h K_C,hᵀ + qR,h K_Rᵀ)/√(dN+dR)','q_latent,h=qC,h W_UK,hᵀ; q_latent,h C_KVᵀ = qC,h K_C,hᵀ','A_h=softmax(scores_h); z_h=A_h C_KV','o_h=z_h W_UV,h; Y=concat(o₀,o₁) W_O','toy: 4 vs 12; V3: 576 vs 40,960 (naïve per-head expanded)'][st],note:MT('Toy: B=T=1, S=3, D=4, H=2, dN=dR=dV=rKV=rQ=2. All matrices below are explicit teaching weights.','示例：B=T=1、S=3、D=4、H=2、dN=dR=dV=rKV=rQ=2。以下矩阵均为明确给定的教学权重。'),traces,scope:MT('The down-projection is learned compression, not exact reconstruction of arbitrary X. Absorption exactly preserves this model’s linear algebra. Prefill kernels may materialize expanded K/V. A rotary-shared expanded baseline uses 10 toy scalars, rather than 12 with replicated rotary slices. V3 counts exclude metadata and quantization.','下投影是学习到的压缩，不能精确重建任意 X；吸收则精确保留该模型的线性代数。预填充内核可物化展开 K/V。共享旋转键的展开基线为 10 个示例标量，复制旋转切片的基线才是 12。V3 计数不含元数据及量化。')};
}
