  const flight=payload.animate([{transform:'translate(-50%,-50%)',opacity:1},{transform:`translate(calc(-50% + ${target.left+target.width/2-source.left-source.width/2}px),calc(-50% + ${target.top+target.height/2-source.top-source.height/2}px))`,opacity:1}],{duration:650/state.speed,easing:'cubic-bezier(.2,.7,.2,1)'});
  const subtotal=sum;flight.onfinish=()=>{payload.remove();if(run!==computationState.run)return;out.textContent=trace.sum?modelNum(previous)+' + '+modelNum(term.value)+' = '+modelNum(subtotal)+(done&&trace.denominator?' → ÷'+modelNum(trace.denominator)+' = '+modelNum(trace.result):''):done?finalCopy():MT('Value = '+(typeof term.value==='number'?modelNum(term.value):term.value),'值 = '+(typeof term.value==='number'?modelNum(term.value):term.value));if(done)document.querySelectorAll('.arithmetic-source').forEach(n=>n.classList.remove('arithmetic-source'));};
